3	/**
4	 * The standard Luhn check digit (0-9), computed over the decimal digits contained in a string;
5	 * non-digit characters (such as hyphen separators) are ignored. The single home for the Luhn
6	 * algorithm the owner functions use, so everything that needs a check digit computes it the same
7	 * way — {@link CheckDigit} derives the customer-code check digit through here.
8	 */
9	final class Luhn {
10	
11	    private Luhn() {
12	    }
13	
14	    /** The Luhn check digit over the decimal digits contained in {@code digitsSource}. */
15	    static int of(String digitsSource) {
16	        int sum = 0;
17	        boolean dbl = true;
18	        for (int i = digitsSource.length() - 1; i >= 0; i--) {
19	            char c = digitsSource.charAt(i);
20	            if (c < '0' || c > '9') {
21	                continue;
22	            }
23	            int d = c - '0';
24	            if (dbl) {
25	                d *= 2;
26	                if (d > 9) {
27	                    d -= 9;
28	                }
29	            }
30	            sum += d;
31	            dbl = !dbl;
32	        }
33	        return (10 - (sum % 10)) % 10;
34	    }
35	}
