21	public record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode, int membershipLevel,
22	        String event) {
23	
24	    /** Discriminator recorded as the event's {@code event} field. */
25	    public static final String EVENT = "OWNER_CREATED";
26	
27	    /** Process-wide source of the monotonically increasing {@code seq}. */
28	    private static final AtomicLong SEQUENCE = new AtomicLong();
29	
30	    /**
31	     * Builds the next event for the given saved owner, allocating a fresh {@code seq}. The owner's
32	     * current primary identifier ({@link Owner#getCustomerCode()}) is captured as {@code customerCode}
33	     * and its numeric {@link MembershipLevel} is captured as {@code membershipLevel}.
34	     */
35	    public static OwnerCreatedEvent of(Owner owner) {
36	        return new OwnerCreatedEvent(SEQUENCE.incrementAndGet(), owner.getId(), owner.getCustomerCode(),
