48	        json.append(",\"ownerId\":").append(ownerId);
49	        json.append(",\"customerCode\":").append(quote(customerCode));
50	        json.append(",\"membershipLevel\":").append(membershipLevel);
51	        json.append(",\"event\":").append(quote(event));
52	        json.append('}');
53	        return json.toString();
54	    }
