56	    /** JSON string literal for {@code value}, or the bare {@code null} literal when it is absent. */
57	    private static String quote(String value) {
58	        if (value == null) {
59	            return "null";
60	        }
61	        StringBuilder out = new StringBuilder(value.length() + 2);
62	        out.append('"');
63	        for (int i = 0; i < value.length(); i++) {
64	            char c = value.charAt(i);
65	            switch (c) {
66	                case '"' -> out.append("\\\"");
67	                case '\\' -> out.append("\\\\");
68	                case '\n' -> out.append("\\n");
69	                case '\r' -> out.append("\\r");
70	                case '\t' -> out.append("\\t");
