package org.springframework.samples.petclinic.rest.function.owner;

/**
 * The standard Luhn check digit (0-9), computed over the decimal digits contained in a string;
 * non-digit characters (such as hyphen separators) are ignored. The single home for the Luhn
 * algorithm the owner functions use, so everything that needs a check digit computes it the same
 * way — {@link CheckDigit} derives the customer-code check digit through here.
 */
final class Luhn {

    private Luhn() {
    }

    /** The Luhn check digit over the decimal digits contained in {@code digitsSource}. */
    static int of(String digitsSource) {
        int sum = 0;
        boolean dbl = true;
        for (int i = digitsSource.length() - 1; i >= 0; i--) {
            char c = digitsSource.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * SHA-256 hashing to a hexadecimal string — the single place the owner functions compute a digest,
 * so everything that derives a value from a hash encodes it the same way. {@link Household#id(String,
 * String)} and {@link AssignCustomerCode} both hash through here; a caller that wants a short,
 * upper-case code takes a prefix of {@link #hex(String)} and upper-cases it.
 */
final class Sha256 {

    private Sha256() {
    }

    /** Full lower-case hex SHA-256 of the UTF-8 bytes of {@code input} (64 characters). */
    static String hex(String input) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }
}

